import{_ as e,o as a,c as d,a3 as s}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Roadmap | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/roadmap"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/roadmap"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/roadmap"}]]},"headers":[],"relativePath":"xclang/design/roadmap.md","filePath":"en/xclang/design/roadmap.md","lastUpdated":1794509097000}'),n={name:"xclang/design/roadmap.md"};function r(i,t,o,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Every target and feature that no release carries yet has one row on this page, with one status word. Other pages link to that row instead of restating the status. What is already in a release is documented on its own page, and what each release changed is in the <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>.</p><table tabindex="0"><thead><tr><th>status</th><th>meaning</th></tr></thead><tbody><tr><td><span class="status-badge ok">Supported</span></td><td>In a release.</td></tr><tr><td><span class="status-badge warn">Unreleased</span></td><td>On <code>main</code> and tested by CI, but no release carries it.</td></tr><tr><td><span class="status-badge note">Planned</span></td><td>Decided, and in no release yet. It may be in progress on a branch.</td></tr><tr><td><span class="status-badge note">In research</span></td><td>Wanted. Whether it can be done well is still open.</td></tr><tr><td><span class="status-badge note">Considered</span></td><td>Wanted. Its form or its cost is still open.</td></tr><tr><td><span class="status-badge off">Not planned</span></td><td>Out of scope by design.</td></tr></tbody></table><h2 id="the-vision" tabindex="-1">The Vision <a class="header-anchor" href="#the-vision" aria-label="Permalink to &quot;The Vision&quot;">​</a></h2><p>xclang&#39;s goal is to give <code>clang</code> what <code>rustup</code>, <code>cross-rs</code> and <code>cargo-zigbuild</code> give Rust: one compiler for every target. The common targets ship in every host archive, vendor SDKs that cannot be redistributed are fetched from the vendor by the user, and C++ runtimes can be built from source on demand (<a href="./../guide/what-is-xclang">what is xclang?</a>, <a href="./../guide/cross-compiling">cross-compiling</a>). Additional targets beyond the bundled set will be published as separate target archives fetched when a build needs them. Every target follows the <a href="./hermeticity">hermeticity</a> rule: a program depends at run time only on the OS libraries that cannot be redistributed, and links everything else statically.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><p>A target&#39;s tier describes how CI tests it (<a href="./../guide/cross-compiling#targets-and-hosts">targets and hosts</a>): Tier 1 runs tests natively on a GitHub-hosted runner (including <code>x86</code> binaries on <code>x86_64</code> Windows and WebAssembly binaries under <code>wasmtime</code>), Tier 2 runs tests under emulation or virtualization, and Tier 3 compiles and links without running. A Tier 3 target may build its runtimes <a href="./../features/runtimes-from-source">from source on demand</a> rather than shipping prebuilt archives. &quot;The user (SDK)&quot; means the target requires a vendor SDK fetched by the user under the vendor&#39;s license.</p><table tabindex="0"><thead><tr><th>target</th><th>C runtime</th><th>from</th><th>tier</th><th>status</th></tr></thead><tbody><tr><td><a id="windows-x86-msvc"></a>Windows x86 (MSVC)</td><td>Microsoft&#39;s CRT and STL, Windows SDK</td><td>the user (SDK)</td><td>1</td><td><span class="status-badge note">In research</span></td></tr><tr><td><a id="windows-7"></a>Windows 7 and XP (MSVC)</td><td>Microsoft&#39;s CRT, static, with YY-Thunks</td><td>the user (SDK)</td><td>3</td><td><span class="status-badge note">In research</span></td></tr><tr><td><a id="windows-x86-mingw"></a>Windows x86 (MinGW)</td><td>mingw-w64, UCRT</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="arm64ec"></a>Windows arm64ec</td><td>Microsoft&#39;s ARM64EC libraries</td><td>the user (SDK)</td><td>3</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="msvcrt"></a>Windows (MinGW) on msvcrt, before Windows 10</td><td>msvcrt</td><td></td><td></td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="glibc-newer"></a>Linux x64, arm64 with a newer glibc</td><td>glibc 2.28</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="linux-architectures"></a>Linux x86</td><td>glibc 2.17</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux armv7 (hard float)</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux riscv64</td><td>glibc 2.31</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux ppc64le, s390x</td><td>glibc 2.17</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td>Linux loongarch64</td><td>glibc 2.36</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="musl-architectures"></a>Linux riscv64, armv7 (musl)</td><td>musl</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="wasm"></a>WebAssembly (<code>wasm32-wasip1</code>, <code>wasm32-wasip2</code>)</td><td>wasi-libc</td><td>xclang</td><td>1</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="android"></a>Android arm64, x64, armv7</td><td>bionic</td><td>the user, from the NDK (SDK)</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="openharmony"></a>OpenHarmony arm64</td><td>OpenHarmony&#39;s musl</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="freebsd"></a>FreeBSD x64, arm64</td><td>FreeBSD 14&#39;s libc</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="bsd"></a>OpenBSD, NetBSD</td><td>their libc</td><td>xclang</td><td>3</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="bare-metal"></a>Bare metal: Arm Cortex-M, -R, -A, AArch64, RISC-V</td><td>picolibc</td><td>xclang</td><td>2</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="ios"></a>iOS, tvOS, watchOS, visionOS, their simulators</td><td>Apple&#39;s SDKs</td><td>the user, from full Xcode (SDK)</td><td>3</td><td><span class="status-badge note">In research</span></td></tr><tr><td><a id="emscripten"></a>Emscripten</td><td>Emscripten&#39;s own</td><td>emsdk</td><td></td><td><span class="status-badge off">Not planned</span></td></tr></tbody></table><ul><li><strong>A newer glibc</strong>: <code>x86_64</code> and <code>aarch64</code> Linux targets for programs that need features absent from glibc 2.17, such as <code>-static-pie</code> and newer C library interfaces, paired with the same static <code>libc++</code> and <code>compiler-rt</code>.</li><li><strong>Other Linux architectures</strong>: each uses the oldest glibc version available for its architecture (<code>riscv64</code> and <code>loongarch64</code> have no glibc 2.17), with the sanitizers <code>compiler-rt</code> supports on that architecture.</li><li><strong>WebAssembly</strong>: <code>wasm32-wasip2</code> links with <code>wasm-component-ld</code> bundled in each host archive; C++ exceptions are opt-in.</li><li><strong>Android</strong>: builds against the NDK&#39;s sysroot with xclang&#39;s static <code>libc++</code> configured in the NDK&#39;s inline ABI namespace (<code>__ndk1</code>).</li><li><strong>iOS and Apple&#39;s other device platforms</strong>: their SDKs ship only in full Xcode (which requires an Apple ID to download), and their C++ runtimes will likely be built <a href="./../features/runtimes-from-source">from source on demand</a>.</li><li><strong>Windows 7 and XP</strong>: the MSVC target linked against the static CRT and <a href="https://github.com/Chuyu-Team/YY-Thunks" target="_blank" rel="noreferrer">YY-Thunks</a> for APIs missing on older Windows versions (<code>mingw-w64</code> with <code>libc++</code> cannot target XP; Windows 9x is out of scope).</li><li><strong><code>msvcrt</code></strong>: xclang&#39;s MinGW targets use UCRT (Windows 10 and later); a MinGW variant targeting the legacy <code>msvcrt.dll</code> is not planned.</li><li><strong>Emscripten</strong>: <code>emsdk</code> provides its own complete toolchain, so Emscripten is not an xclang target.</li></ul><h2 id="the-xclang-command" tabindex="-1">The xclang Command <a class="header-anchor" href="#the-xclang-command" aria-label="Permalink to &quot;The xclang Command&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="target-archives"></a>Target archives and a release index, for <code>xclang target add</code></td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="fetched-targets-in-build-systems"></a>Fetched targets in the CMake package and the Bazel module</td><td><span class="status-badge note">Planned</span></td></tr></tbody></table><p><a href="./../reference/xclang-command#targets"><code>xclang target add</code></a> is built to unpack a per-target archive of the same release into the toolchain directory (sysroot, prebuilt runtimes, <code>compiler-rt</code>, config files and C runtime license notices) using a release manifest that records each target archive&#39;s URL, <code>sha256</code>, size, tier and required vendor SDK. Once releases publish target archives, the CMake package and the Bazel module will configure and register fetched targets alongside the bundled ones.</p><h2 id="runtimes-and-tools" tabindex="-1">Runtimes and Tools <a class="header-anchor" href="#runtimes-and-tools" aria-label="Permalink to &quot;Runtimes and Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="runtimes-msvc"></a>Runtimes from source for the MSVC targets</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="runtimes-bazel-lto"></a>LTO of the runtimes from source with the program, in Bazel</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="musl-sanitizers"></a>ASan, TSan, LSan and libFuzzer for musl targets, with a dynamically linked musl (Alpine&#39;s way)</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="libgcc-s-script"></a><code>libgcc_s.a</code> as a linker script naming libunwind, for Rust&#39;s Linux targets</td><td><span class="status-badge note">Considered</span></td></tr><tr><td><a id="openmp"></a>An OpenMP runtime</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="tool-binaries"></a>clang-format, clang-tidy and clangd programs</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="shared-runtime"></a>A shared C++ runtime across shared libraries</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="conda-forge"></a>A compiler for building conda-forge packages</td><td><span class="status-badge off">Not planned</span></td></tr><tr><td><a id="libclang-msvc"></a>libclang for programs built with the MSVC ABI</td><td><span class="status-badge off">Not planned</span></td></tr></tbody></table><ul><li><strong>Runtimes from source for MSVC targets, and ThinLTO in Bazel</strong>: extending <a href="./../features/runtimes-from-source">runtimes from source</a> to compile <code>libc++</code> on <code>vcruntime</code> with <code>clang-cl</code> against the fetched Windows SDK; and exposing source-built runtimes in Bazel as <code>cc_library</code> dependencies so Bazel runs ThinLTO backend actions on their bitcode objects.</li><li><strong>Sanitizers for musl targets</strong>: ASan, TSan and LSan intercept C library functions through <code>dlsym</code>, which static musl executables do not have (<a href="./../features/sanitizers#musl-targets">sanitizers</a>). Supporting them requires a musl target variant that links dynamically against <code>libc.so</code> as Alpine Linux does.</li><li><strong><code>libgcc_s.a</code> as a linker script</strong>: replacing the empty <code>libgcc_s.a</code> archive in the Linux sysroots with <code>INPUT(-lunwind)</code> so manual Cargo configurations for <code>*-unknown-linux-gnu</code> link without adding <code>-Clink-arg=-l:libunwind.a</code> (<a href="./../integrations/cargo#without-xclang-cargo">without <code>xclang cargo</code></a>).</li><li><strong>Not planned</strong>: xclang is a compiler toolchain, and editor or linter tools link <a href="./../features/libclang"><code>libclang</code></a> directly; <code>libc++</code> is linked statically into each binary rather than shared across dynamic libraries (<a href="./hermeticity#one-libc-per-shared-object">one <code>libc++</code> per shared object</a>); conda-forge recipes use conda-forge&#39;s dynamically linked compiler packages; and <code>libclang</code> is built for the six hosts (MinGW on Windows, for clice) rather than the MSVC ABI.</li></ul><h2 id="speed" tabindex="-1">Speed <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;Speed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="pgo-training"></a>A PGO training that covers Objective-C, clang-cl, Mach-O links and libclang&#39;s clang-tidy checks</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="bolt"></a>BOLT for the Linux hosts&#39; clang and lld, on top of PGO and ThinLTO</td><td><span class="status-badge note">In research</span></td></tr></tbody></table><p>The <a href="./pgo#the-training">PGO training corpus</a> is widened between releases.</p><h2 id="reproducibility-and-supply-chain" tabindex="-1">Reproducibility and Supply Chain <a class="header-anchor" href="#reproducibility-and-supply-chain" aria-label="Permalink to &quot;Reproducibility and Supply Chain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="cmake-relative-paths"></a>Relative paths in the debug information of CMake builds</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="immutable-releases"></a>Immutable GitHub releases</td><td><span class="status-badge note">Planned</span></td></tr><tr><td><a id="slsa"></a>SLSA provenance attestations</td><td><span class="status-badge note">Planned</span></td></tr></tbody></table><ul><li><strong>Relative debug paths in CMake</strong>: CMake builds currently record the build directory&#39;s absolute paths in DWARF and Mach-O debug maps, whereas Bazel builds record paths relative to the execution root (<a href="./../features/debugging#paths-in-debug-information">paths in debug information</a>).</li><li><strong>Immutable GitHub releases and SLSA provenance</strong>: preventing a published archive and <code>SHA256SUMS</code> from being replaced together on GitHub (<a href="./../reference/releases#checking-a-download">checking a download</a>), and attaching verifiable build provenance attestations tying each release asset to its commit and GitHub Actions workflow run.</li></ul><h2 id="following-llvm" tabindex="-1">Following LLVM <a class="header-anchor" href="#following-llvm" aria-label="Permalink to &quot;Following LLVM&quot;">​</a></h2><table tabindex="0"><thead><tr><th>item</th><th>status</th></tr></thead><tbody><tr><td><a id="llvm-releases"></a>LLVM 24.x, and every 23.1 release still to come, each as it is released</td><td><span class="status-badge note">Planned</span></td></tr></tbody></table><p>Each upstream LLVM release is built with the <a href="./../reference/patches">patch series</a> checked against it, dropping patches that upstream has merged.</p><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><p>Design choices inside the items above:</p><ul><li><strong>Android&#39;s sysroot</strong>: whether <code>xclang sdk fetch</code> downloads only the needed files from Google&#39;s NDK or xclang redistributes the sysroot directly.</li><li><strong>The runtimes of Apple&#39;s device platforms</strong>: whether to publish prebuilt archives or build them only from source on demand, since Apple&#39;s license treats device platform libraries separately from macOS libraries.</li><li><strong>A glibc newer than 2.17</strong>: whether a build selects it with a named config file (<code>--config=</code>) or a distinct target triple spelling.</li><li><strong>Where fetched targets are stored</strong>: inside the toolchain directory only, or also in a user-selected directory.</li></ul>',27)])])}const u=e(n,[["render",r]]);export{p as __pageData,u as default};
